text:
{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "麻烦",
      "role": "CONTEXT",
      "explanation": "Polite request marker; it does not add, remove, or modify any executable action."
    },
    {
      "text": "先",
      "role": "RELATION",
      "explanation": "Marks the following walk as the first action in the sequence."
    },
    {
      "text": "往前走六米",
      "role": "ACTION",
      "explanation": "Requests walk_forward with distance_m=6; 六米 is a positive finite distance."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Clause separator; it does not change action order or parameters."
    },
    {
      "text": "接着",
      "role": "RELATION",
      "explanation": "Marks the following turn as the next action after the first walk."
    },
    {
      "text": "顺时针转45度",
      "role": "ACTION",
      "explanation": "Requests a clockwise turn of 45 degrees, i.e. angle_deg=-45; it is nonzero, finite, and legal."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Clause separator; it does not change action order or parameters."
    },
    {
      "text": "然后",
      "role": "RELATION",
      "explanation": "Marks the following walk as the next action after the turn."
    },
    {
      "text": "前进4m",
      "role": "ACTION",
      "explanation": "Requests walk_forward with distance_m=4; m is read as meters."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Clause separator; it does not change action order or parameters."
    },
    {
      "text": "再",
      "role": "RELATION",
      "explanation": "Marks the stop as the final action after the second walk."
    },
    {
      "text": "停止",
      "role": "ACTION",
      "explanation": "Requests stop with no parameters as the last action."
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "Source requests exactly four actions once each: walk_forward 6 m, clockwise turn 45 degrees, walk_forward 4 m, and stop. No edited, alternative, or additional action is introduced."
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "The sequence markers 先, 接着, 然后, and 再 establish one exact linear order: walk 6 m, turn clockwise 45 degrees, walk 4 m, stop."
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "There is no correction, replacement, or edit clause in the source; no prior action or parameter is changed."
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "No action or span is stated to repeat; each requested action occurs once."
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "No pronouns or ordinal back-references require resolution. The second walk has its own distance 4m, and stop has no omitted argument."
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "The source gives only sequential relations via 先, 接着, 然后, and 再; no simultaneity, waiting, or completion condition creates another representable timing."
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "No choice, scope, ordering, or relationship is explicitly left unresolved in the source."
    }
  }
}
